import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce(torch::Tensor x, int64_t dim);
"""

max_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>
#include <vector>
#include <cstdint>
#include <algorithm>

using namespace cute;

template <int Threads>
__global__ void max_reduce_dim_kernel(const float* __restrict__ X,
                                      float* __restrict__ Y,
                                      int outer,
                                      int R,
                                      int inner)
{
  const int64_t num_out = (int64_t)outer * (int64_t)inner;
  const int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       idx < num_out;
       idx += stride) {
    const int o = (int)(idx / inner);
    const int i = (int)(idx - (int64_t)o * inner);
    const float* p = X + (int64_t)o * (int64_t)R * (int64_t)inner + i;
    const int64_t step = (int64_t)inner;
    float acc = -INFINITY;
    #pragma unroll 4
    for (int r = 0; r < R; ++r) {
      acc = fmaxf(acc, __ldg(p + (int64_t)r * step));
    }
    Y[idx] = acc;
  }
}
template <int Threads>
__global__ void max_reduce_dim_kernel_vec4(const float* __restrict__ X,
                                           float* __restrict__ Y,
                                           int outer,
                                           int R,
                                           int inner)
{
  const int vec_inner = inner >> 2;
  const int64_t num_out = (int64_t)outer * (int64_t)vec_inner;
  const int64_t stride = (int64_t)blockDim.x * gridDim.x;
  const int64_t step = (int64_t)inner;
  for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       idx < num_out;
       idx += stride) {
    const int o = (int)(idx / vec_inner);
    const int v = (int)(idx - (int64_t)o * vec_inner);
    const int i = v << 2;
    const float* p = X + ((int64_t)o * (int64_t)R) * step + i;
    float4 acc = make_float4(-INFINITY, -INFINITY, -INFINITY, -INFINITY);
    #pragma unroll 4
    for (int r = 0; r < R; ++r) {
      const float4 x = __ldg(reinterpret_cast<const float4*>(p + (int64_t)r * step));
      acc.x = fmaxf(acc.x, x.x);
      acc.y = fmaxf(acc.y, x.y);
      acc.z = fmaxf(acc.z, x.z);
      acc.w = fmaxf(acc.w, x.w);
    }
    reinterpret_cast<float4*>(Y + (int64_t)o * step + i)[0] = acc;
  }
}
template <int Threads>
__global__ void max_reduce_dim_kernel_vec4u(const float* __restrict__ X,
                                            float* __restrict__ Y,
                                            int outer,
                                            int R,
                                            int inner,
                                            int64_t numel)
{
  const int vec_inner = inner >> 2;
  const int tail = inner & 3;
  const int64_t num_out = (int64_t)outer * (int64_t)vec_inner;
  const int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       idx < num_out;
       idx += stride) {
    const int o = (int)(idx / vec_inner);
    const int v = (int)(idx - (int64_t)o * vec_inner);
    const int i = v << 2;
    const int64_t slab = (int64_t)o * (int64_t)R * (int64_t)inner;
    unsigned f = (unsigned)((slab + i) & 3);
    float4 acc = make_float4(-INFINITY, -INFINITY, -INFINITY, -INFINITY);
    #pragma unroll 4
    for (int r = 0; r < R; ++r) {
      const int64_t off = slab + (int64_t)r * (int64_t)inner + i;
      const int64_t aoff = off & ~(int64_t)3;
      float4 x;
      if (f == 0u) {
        x = __ldg(reinterpret_cast<const float4*>(X + aoff));
      } else if (aoff + 8 <= numel) {
        const float4 a = __ldg(reinterpret_cast<const float4*>(X + aoff));
        const float4 b = __ldg(reinterpret_cast<const float4*>(X + aoff + 4));
        if (f == 1u)      x = make_float4(a.y, a.z, a.w, b.x);
        else if (f == 2u) x = make_float4(a.z, a.w, b.x, b.y);
        else              x = make_float4(a.w, b.x, b.y, b.z);
      } else {
        x = make_float4(__ldg(X + off), __ldg(X + off + 1),
                        __ldg(X + off + 2), __ldg(X + off + 3));
      }
      acc.x = fmaxf(acc.x, x.x);
      acc.y = fmaxf(acc.y, x.y);
      acc.z = fmaxf(acc.z, x.z);
      acc.w = fmaxf(acc.w, x.w);
      f = (f + (unsigned)inner) & 3u;
    }
    float* yp = Y + (int64_t)o * (int64_t)inner + i;
    yp[0] = acc.x;
    yp[1] = acc.y;
    yp[2] = acc.z;
    yp[3] = acc.w;
  }
  const int64_t tail_out = (int64_t)outer * (int64_t)tail;
  for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       idx < tail_out;
       idx += stride) {
    const int o = (int)(idx / tail);
    const int j = (int)(idx - (int64_t)o * tail);
    const int i = (vec_inner << 2) + j;
    const float* p = X + (int64_t)o * (int64_t)R * (int64_t)inner + i;
    float acc = -INFINITY;
    for (int r = 0; r < R; ++r) {
      acc = fmaxf(acc, __ldg(p + (int64_t)r * (int64_t)inner));
    }
    Y[(int64_t)o * (int64_t)inner + i] = acc;
  }
}
torch::Tensor max_reduce(torch::Tensor x, int64_t dim)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
  auto x_c = x.contiguous();
  int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");
  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= x_c.size(d);
  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t d = 0; d < nd; ++d) {
    if (d != dim) out_sizes.push_back(x_c.size(d));
  }
  auto y = torch::empty(out_sizes, x_c.options());
  if (outer == 0 || inner == 0) return y;
  constexpr int Threads = 256;
  const bool vec4_ok = (R > 0) && ((inner & 3) == 0) && (inner >= 4);
  const bool vec4u_ok = !vec4_ok && (R > 0) && (inner >= 4);
  const int64_t work_items = vec4_ok ? (outer * (inner >> 2))
                             : (vec4u_ok ? (outer * (inner >> 2) + outer * (inner & 3))
                                         : (outer * inner));
  const int64_t wanted_blocks = (work_items + Threads - 1) / Threads;
  const unsigned blocks = (unsigned)std::min<int64_t>(wanted_blocks, (int64_t)2147483647);
  dim3 block(Threads);
  dim3 grid(blocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (vec4_ok) {
    max_reduce_dim_kernel_vec4<Threads><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer,
        (int)R,
        (int)inner);
  } else if (vec4u_ok) {
    max_reduce_dim_kernel_vec4u<Threads><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer,
        (int)R,
        (int)inner,
        (int64_t)x_c.numel());
  } else {
    max_reduce_dim_kernel<Threads><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer,
        (int)R,
        (int)inner);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

max_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=max_cpp_decl,
    cuda_sources=max_cuda_src,
    functions=["max_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using one custom CUTE/CUDA kernel.
    Optimized for the provided case: x is [128, 4096, 4095], dim=1.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = int(dim)
        self._ext = max_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce(x, self.dim)

